import{_ as a,o as s,c as _,a3 as t}from"./chunks/framework.DdpBa4_E.js";const o="/ReadBooks/assets/image-006.LKdHE9ev.jpg",e="/ReadBooks/assets/image-007.DNXVMlN7.jpg",i="/ReadBooks/assets/image-008.INpnUcOu.jpg",r="/ReadBooks/assets/image-009.CAoVWnmE.jpg",l="/ReadBooks/assets/image-010.JpugFpMP.jpg",c="/ReadBooks/assets/image-011.BPgra83p.jpg",g="/ReadBooks/assets/image-012.CQ0Kh9y4.jpg",n="/ReadBooks/assets/image-013.BMcxc76_.jpg",d="/ReadBooks/assets/image-014.D4B_Uz_w.jpg",j=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/attached/30-使用问卷确定伴侣的依恋风格.md","filePath":"books/attached/30-使用问卷确定伴侣的依恋风格.md","lastUpdated":1794298621000}'),m={name:"books/attached/30-使用问卷确定伴侣的依恋风格.md"};function B(k,p,h,y,z,R){return s(),_("div",null,[...p[0]||(p[0]=[t('<h3 id="使用问卷确定伴侣的依恋风格" tabindex="-1">使用问卷确定伴侣的依恋风格 <a class="header-anchor" href="#使用问卷确定伴侣的依恋风格" aria-label="Permalink to &quot;使用问卷确定伴侣的依恋风格&quot;">​</a></h3><p>下面这份问卷，是专门用于评估恋爱或约会对象的依恋风格。</p><p>问卷分为三个部分，每个部分都通过几个例子，来描述某种特质。如果提及的特质与你伴侣大致符合，你就将其标记为“符合”。看完每一种特质以后，你要根据日常生活中的交往和对话，来判断伴侣是否符合这种特质。得分越高，就说明对方越符合该种特质，下面是你的记分键：</p><p>1.非常不符合对方的情况</p><p>2.大致符合对方的情况</p><p>3.非常符合对方的情况</p><p>A部分</p><p><img src="'+o+'" alt="" loading="lazy"></p><p><img src="'+e+'" alt="" loading="lazy"></p><p><img src="'+i+'" alt="" loading="lazy"></p><p>（将第1题到第11题的得分加总）</p><p>A部分的总分：__________</p><p>B部分</p><p><img src="'+r+'" alt="" loading="lazy"></p><p><img src="'+l+'" alt="" loading="lazy"></p><p><img src="'+c+'" alt="" loading="lazy"></p><p>（将第1题到第11题的得分加总）</p><p>B部分的总分：_________</p><p>C部分</p><p><img src="'+g+'" alt="" loading="lazy"></p><p><img src="'+n+'" alt="" loading="lazy"></p><p><img src="'+d+'" alt="" loading="lazy"></p><p>（将第1题到第11题的得分加总）</p><p>C部分的总分：__________</p><p>记分键：（将每种风格的总分，在下述标准下进行对照。）</p><p>1~17分：非常低。你的伴侣显然不属于这种依恋风格。</p><p>18~22分：中等。你的伴侣有表现出这种依恋风格的倾向性。</p><p>23~33分：很高，你的伴侣显然属于这种依恋风格。</p><p>一般来说，在一种风格下的得分越高，就说明伴侣越有可能属于这种风格。在一种风格下的得分达到23分以上，属于这种依恋风格的倾向性就非常明显了。如果你的伴侣在焦虑和回避两种风格下的得分都比较高，可能就属于焦虑——回避型依恋风格。焦虑型与回避型依恋风格的人群，很多行为的外在表现都非常相似，虽然这些类似的行为，可能有着不同的情感认知来源。如果你的伴侣属于这类情况，就需要参见后文中的“黄金法则”，才能做出更为准确的判断。</p><p>A部分得分高于23分：说明你的伴侣是回避型依恋风格。也就是说你的确不能对他表现得太过亲密。安全型和焦虑型依恋风格的人，有着亲近的本能；然而回避型依恋风格的人，他们在感情中的快乐来源于思念。他们的脑机制与其他人无异，也需要爱和关怀，但当他们产生爱与依恋的需求时，过度的亲密却会令他们感到束缚。他们在日常生活和交流中，都或多或少喜欢逃避。即使是在选择电视节目，或者某种方式时，他们都带着对私人空间和独立自主的一种坚持。你必须经常向他们做出一些妥协，否则他们就会选择不断逃避。研究显示，回避型依恋风格的人，很难去跟同样风格的人恋爱，因为他们生来就缺乏那种人际间的黏合剂，两人很难共处下去。</p><p>B部分得分高于23分：说明你的伴侣属于安全型依恋风格。这类人有亲密需要，同时他们不会对拒绝过度敏感。他们善于沟通，知道如何直截了当地表达自己的诉求，而不是通过责难来传达给对方。跟安全型依恋风格的人相处，你无须向他提出亲密的请求，这是水到渠成的事。而这种自由，让你们双方都能尽情享受生活，同时共同成长。他们善于倾听你的观点，会尽力将事情通过双方都能接受的方式来妥善解决。他们对于亲密关系，有着这样一种内在理解：实际上，伴侣的快乐就是自己的快乐。而这种高质量的关系，能让你们做最真实独立的自己。而相关研究表明，这一点也是对一个人的幸福和愉悦感，影响最为巨大的因素之一。</p><p>C部分得分高于23分：说明你的伴侣属于焦虑型依恋风格。焦虑型依恋风格的人群，非常渴望亲密，但又对亲密关系中任何一点点可能的威胁都异常敏感。有时候，他们会将你无意中的行为，解读为对亲密关系的威胁。当这一切发生时，他们会被恐惧所淹没，然而又缺乏有效的沟通技巧来将这种不安传达给你。反之，他们会表现出异常的情绪化和歇斯底里。而在他们的过度敏感与焦虑不安之间，正好形成了一种对双方关系致命的恶性循环。这听上去好像很吓人，但如果你足够敏锐地观察到，也足够娴熟地化解他们的担忧，这对你来说也就不算什么了。如果你做到这一点，他们将对你充满爱慕，甘愿为你付出。如果你对他们的需要，报以温暖与安全感，他们的这种敏感性会变得相对稳定，此时的他们会乐于投你所好，而且非常热心也细心地对待你。不仅如此，他也将逐渐学会如何向你表达心中的不安，你也就渐渐不必绞尽脑汁猜他们的心思了。</p>',32)])])}const u=a(m,[["render",B]]);export{j as __pageData,u as default};
